    @unittest.skipUnless(have("ssh-keygen"), "ssh-keygen not installed")
    def test_without_a_master_tor_leaves_through_a_commercial_vpn(self):
        """The owner's rule: Tor never on the home line, always behind a VPN. Without a master, a
        commercial VPN is the machine's exit; the home network is not routed into it."""
        alone = dict(self.ANSWERS, master_where="none", master_address="",
                     nodes=[{"name": "mango", "preset": "cloud", "address": "192.168.2.30/16"}])
        answers = os.path.join(self.tmp, "answers.json")
        write(answers, json.dumps(alone))
        dest = os.path.join(self.tmp, "fleet.yaml")
        self.assertEqual(self.run_cli("init", dest, "--answers", answers, "--no-store")[0], 0)
        data = yaml.safe_load(util.read_text(dest))
        node = data["hosts"]["mango"]["node"]
        node["modules"] = node["modules"] + ["onion"]
        node["onion"] = {"services": {"cloud": {}}}
        write(dest, yaml.safe_dump(data, sort_keys=False))
        rc, out, err = self.run_cli("onion", dest, "cloud.mango")
        self.assertIn("a commercial VPN", err)                                    # not on the home line by itself
        self.assertIn("onion: { without_vpn: true }", err)                        # unless the owner chooses it
        node["onion"]["without_vpn"] = True
        write(dest, yaml.safe_dump(data, sort_keys=False))
        rc, out, err = self.run_cli("onion", dest, "cloud.mango")
        self.assertIn("your internet provider can see", err)
        del node["onion"]["without_vpn"]
        node["modules"] = node["modules"] + ["vpn-client"]
        node["vpn-client"] = {"vpn_provider": "mullvad", "wireguard_addresses": "10.66.1.2/32",
                              "wireguard_private_key": "aGVsbG8taGVsbG8taGVsbG8taGVsbG8taGVsbG8tMDA="}
        write(dest, yaml.safe_dump(data, sort_keys=False))
        o = os.path.join(self.tmp, "out")
        rc, out, err = self.run_cli("render", dest, "mango", "-o", o)
        self.assertEqual(rc, 0, err)
        with open(os.path.join(o, "mango", "mango.stack", "docker-compose.yml")) as f:
            svcs = yaml.safe_load(f)["services"]
        self.assertEqual(svcs["kn-onion"]["network_mode"], "service:kn-vpn-client")
        self.assertIn("KS_STACK_MESH_VIA=''", util.read_text(os.path.join(o, "mango", "mango.stack", "stack.sh")))

    @unittest.skipUnless(have("ssh-keygen"), "ssh-keygen not installed")
    def test_a_network_without_a_master_gets_one(self):
        """docs/design/no-master.md: `add FLEET master` puts the machines at home back on the VPN."""
        alone = dict(self.ANSWERS, master_where="none", master_address="",
                     nodes=[{"name": "mango", "preset": "cloud", "address": "192.168.2.30/16"}])
        answers = os.path.join(self.tmp, "answers.json")
        write(answers, json.dumps(alone))
        dest = os.path.join(self.tmp, "fleet.yaml")
        self.assertEqual(self.run_cli("init", dest, "--answers", answers)[0], 0)
        with open(dest, "a") as fh:
            fh.write("  # a comment kept by hand\n")
        # a node added now is off the VPN too: there is none
        rc, out, err = self.run_cli("add", dest, "node", "quince")
        self.assertEqual(rc, 0, err)
        hosts = yaml.safe_load(util.read_text(dest))["hosts"]
        self.assertIs(hosts["quince"]["node"]["vpn"], False)
        self.assertNotIn("vpn-client", hosts["quince"]["node"])
        self.assertIn("fixed address", err + out)
        # quince left through a commercial VPN of its own (Tor, downloads)
        data = yaml.safe_load(util.read_text(dest))
        data["hosts"]["quince"]["node"]["vpn-client"] = {"vpn_provider": "mullvad", "wireguard_addresses": "10.66.1.2/32",
                                                        "wireguard_private_key": "test-key-only"}
        data["hosts"]["quince"]["node"]["modules"] = ["vpn-client", "reverse-proxy"]
        write(dest, yaml.safe_dump(data, sort_keys=False))
        # a master comes: every machine at home goes onto the VPN
        rc, out, err = self.run_cli("add", dest, "master", "trifle", "--address", "203.0.113.7")
        self.assertEqual(rc, 0, err)
        hosts = yaml.safe_load(util.read_text(dest))["hosts"]
        self.assertEqual(hosts["trifle"]["master"]["vpn-server"]["wg_host"], "203.0.113.7")
        # encrypted, as every machine: its key given over SSH in its initramfs
        self.assertEqual((hosts["trifle"]["debian"], hosts["trifle"]["unlock"]), ({"encrypt": True}, {"ssh": True}))
        for n in ("mango", "quince"):
            self.assertIs(hosts[n]["node"]["vpn"], True)
            self.assertEqual(hosts[n]["node"]["vpn-client"], {"wireguard_config": "secrets/%s.home.conf" % n})
        self.assertEqual(hosts["mango"]["node"]["modules"][:2], ["vpn-client", "dns"])
        # quince's provider is not thrown away: the new master leaves through it, for everyone
        self.assertEqual(hosts["trifle"]["master"]["vpn-client"]["vpn_provider"], "mullvad")
        self.assertEqual(hosts["trifle"]["master"]["modules"][0], "vpn-client")
        self.assertIn("exit of trifle", err + out)
        self.assertIn("enroll", err + out)
        rc, out, err = self.run_cli("list", dest, "--porcelain")
        listed = {h["name"]: h for h in json.loads(out)["hosts"]}
        self.assertEqual((listed["trifle"]["phase"], listed["mango"]["phase"]), ("build", "enroll"))

