class TestWake(Base):
    """Wake-on-LAN (wake.py): what an apply learns, which machine sends the packet, and how."""

    def lan_fleet(self):
        return self.fleet({"defaults": self.base_defaults(), "hosts": {
            "gate": {"role": "master", "target": "debian", "master": self.master()},
            "papaya": {"role": "node", "network": {"dhcp": False, "address": "192.168.2.30/24", "gateway": "192.168.2.1"},
                       "node": {"vpn-client": {"wireguard_config": "secrets/wg.conf"}, "vpn_ip": "10.8.0.25", "preset": "minimal"}},
            "fig": {"role": "node", "network": {"dhcp": False, "address": "192.168.2.40/24", "gateway": "192.168.2.1", "wol": True},
                    "node": {"vpn-client": {"wireguard_config": "secrets/wg.conf"}, "vpn_ip": "10.8.0.26", "preset": "minimal"}},
            "away": {"role": "node", "network": {"dhcp": False, "address": "192.168.2.50/24", "gateway": "192.168.2.1", "site": "office"},
                     "node": {"vpn-client": {"wireguard_config": "secrets/wg.conf"}, "vpn_ip": "10.8.0.27", "preset": "minimal"}}}})

    def test_what_an_apply_learns_and_the_packet(self):
        self.assertEqual(wakemod.parse("enp1s0 52:54:00:85:81:FA 192.168.2.71/16\nwol g\n"),
                         {"card": "enp1s0", "mac": "52:54:00:85:81:fa", "address": "192.168.2.71/16", "wol": "g"})
        self.assertEqual(wakemod.parse("nothing here"), {})
        m = wakemod.magic("52:54:00:85:81:fa")
        self.assertEqual((len(m), m[:6], m[6:12]), (102, b"\xff" * 6, bytes.fromhex("52540085 81fa".replace(" ", ""))))
        f = self.lan_fleet()
        calls = []

        def run(tgt, script, data=None):
            calls.append(script)
            return b"eth0 02:00:00:00:00:40 192.168.2.40/24\nwol d\n" if "Wake-on" in script else b""
        with mock.patch.object(util, "warn") as warned:
            wakemod.after_apply(f.hosts["fig"], "core@fig", runner=run)
        self.assertIn("WakeOnLan=magic", calls[0])                       # network.wol: on at the card
        self.assertEqual(wakemod.known(f)["fig"]["mac"], "02:00:00:00:00:40")
        self.assertIn("does not wake on a magic packet yet", str(warned.call_args))
        wakemod.after_apply(f.hosts["papaya"], "core@papaya", runner=lambda t, s, d=None: b"")
        self.assertNotIn("papaya", wakemod.known(f))                     # nothing learned: nothing kept

    def test_a_machine_of_its_lan_sends_it(self):
        f = self.lan_fleet()
        wakemod.remember(f, "fig", {"card": "eth0", "mac": "02:00:00:00:00:40", "address": "192.168.2.40/24"})
        self.assertEqual([h.name for h in wakemod.wakers(f, f.hosts["fig"], ipaddress.ip_network("192.168.2.0/24"))], ["papaya"])
        sent = []

        def run(tgt, script, data=None):
            if tgt == "core@nobody":
                raise KiwiError("ssh: no answer")
            sent.append((tgt, script))
            return b"sent on eth0\n"
        self.assertEqual(wakemod.wake(f, f.hosts["fig"], reach=lambda h: "core@" + h.name, runner=run), "papaya")
        tgt, script = sent[0]
        self.assertEqual(tgt, "core@papaya")
        self.assertIn("ip neigh replace 192.168.2.40 lladdr 02:00:00:00:00:40", script)
        self.assertIn("/dev/udp/192.168.2.40/9", script)
        self.assertIn("\\xff\\xff\\xff\\xff\\xff\\xff\\x02\\x00", script)
        # none answers: said; no MAC: said; --via another
        with self.assertRaises(KiwiError) as e:
            wakemod.wake(f, f.hosts["fig"], reach=lambda h: "core@nobody", runner=run)
        self.assertIn("no machine of its LAN sent the packet: papaya (ssh: no answer)", str(e.exception))
        with self.assertRaises(KiwiError) as e:
            wakemod.wake(f, f.hosts["papaya"], reach=lambda h: "core@" + h.name, runner=run)
        self.assertIn("its MAC is not known", str(e.exception))
        self.assertEqual(wakemod.wake(f, f.hosts["papaya"], mac="02:00:00:00:00:30", via="fig",
                                      reach=lambda h: "core@" + h.name, runner=run), "fig")
        rc, out, err = TestManage.run_cli(self, "validate", f.path)
        self.assertEqual(rc, 0, err)
        data = yaml.safe_load(util.read_text(f.path))
        data["hosts"]["fig"]["network"]["mac"] = "not-a-mac"
        write(f.path, yaml.safe_dump(data))
        self.assertIn("network.mac must be like", TestManage.run_cli(self, "validate", f.path)[2])


class TestStandby(Base):
    def fleet_with_standby(self, **standby):
        sb = {"target": "debian", "network": {"dhcp": False, "address": "192.168.7.70/24", "gateway": "192.168.7.1"}}
        sb.update(standby)
        master = self.master()
        master["modules"] = ["vpn-client", "vpn-server", "dns", "tor", "reverse-proxy"]
        master["tor"] = {}                                  # its settings go with it on a standby at home
        master["modules"].append("tang")
        master["tang"] = {"rings": {"away": "7501"}}
        return self.fleet({"defaults": self.base_defaults(), "hosts": {
            "gate": {"role": "master", "target": "debian", "admin": {"ssh_port": 41022}, "master": master,
                     "standby": {"gate-b": sb}},
            "store": {"role": "node", "node": {"vpn-client": {"wireguard_config": "secrets/wg.conf"}, "vpn_ip": "10.8.0.9",
                                               "preset": "minimal"}}}})

    def test_a_standby_is_its_master_on_another_machine(self):
        f = self.fleet_with_standby()
        b, gate = f.hosts["gate-b"], f.hosts["gate"]
        self.assertEqual((b.standby_of, b.hostname, b.standby_endpoint), ("gate", gate.hostname, "192.168.7.70"))
        self.assertEqual(f.standbys("gate"), [b])
        self.assertEqual(b.admin["ssh_port"], 41022)                       # its master's, unless its own
        self.assertNotIn("standby", b.overrides)
        self.prepare(gate)
        role_b = self.prepare(b)
        self.assertEqual(role_b.node_type, "master")
        self.assertNotIn("tor", b.modules)                                  # at home: no Tor
        self.assertNotIn("tang", b.modules)                                 # nor its master's ring
        self.assertIn("tor", gate.modules)
        self.assertEqual(b.module_settings["dns"]["pihole_password"], gate.module_settings["dns"]["pihole_password"])
        self.assertEqual(b.module_settings["vpn-server"]["wg_host"], gate.module_settings["vpn-server"]["wg_host"])
        self.assertEqual(backup._wireguard_copy(b), backup._wireguard_copy(gate))     # the master's identity
        self.assertFalse(backup.keep_wireguard(b, None, runner=lambda *a, **k: self.fail("a standby's peers are not kept")))
        self.assertTrue(cli.has_master(f, self.roles))

    def test_list_says_it_is_a_standby(self):
        f = self.fleet_with_standby()
        rc, out, err = TestManage.run_cli(self, "list", f.path, "--porcelain")
        self.assertEqual(rc, 0, err)
        rows = {r["name"]: r for r in json.loads(out)["hosts"]}
        self.assertEqual((rows["gate-b"]["standby_of"], rows["gate"]["standby_of"]), ("gate", ""))
        rc, out, err = TestManage.run_cli(self, "list", f.path)
        self.assertIn("gate's standby: the same master on its own machine", out)

    def test_its_masters_nodes_know_where_it_is(self):
        f = self.fleet_with_standby()
        r = cli.Renderer(f, self.roles, self.tmp, None, self.ms)
        self.assertEqual(r.standby_endpoints(), ["vpn.example.org:51820:41022", "192.168.7.70:51820:41022"])
        bare = self.fleet({"defaults": self.base_defaults(), "hosts": {
            "gate": {"role": "master", "target": "debian", "master": self.master()}}})
        self.assertEqual(cli.Renderer(bare, self.roles, self.tmp, None, self.ms).standby_endpoints(), [])

    def test_the_devices_are_sent_to_the_standby_and_back(self):
        from kiwiserver import watchdog
        f = self.fleet_with_standby()
        calls, state = [], {}

        def point(address):
            calls.append(address)
            return "198.51.100.9"               # where the name pointed before
        kinds = {"gate": "master", "gate-b": "node", "store": "node"}
        watchdog.step(f, kinds, {"gate": False}, state, 0, restart=lambda n: None, point=point)
        self.assertEqual(calls, [])                                                   # not yet: it waits its minutes
        events = watchdog.step(f, kinds, {"gate": False}, state, 16 * 60, restart=lambda n: None, point=point)
        self.assertEqual(calls, ["192.168.7.70"])
        self.assertIn("its devices are sent to its standby gate-b", " ".join(e["text"] for e in events))
        watchdog.step(f, kinds, {"gate": False}, state, 30 * 60, restart=lambda n: None, point=point)
        self.assertEqual(calls, ["192.168.7.70"])                                     # once
        events = watchdog.step(f, kinds, {"gate": True}, state, 40 * 60, restart=lambda n: None, point=point)
        self.assertEqual(calls, ["192.168.7.70", "198.51.100.9"])                    # back where it was
        self.assertEqual(state["pointed"], {})
        self.assertIn("its devices are sent back to it", " ".join(e["text"] for e in events))

    def test_the_name_is_changed_at_the_provider_without_showing_its_token(self):
        from kiwiserver import ddns
        f = self.fleet_with_standby()
        write(f.resolve_path(ddns.FILE), "https://user:s3cret@ddns.example/update?hostname={name}&myip={address}\n")
        seen = []

        def opener(url):
            seen.append(url)
            return 200, "good 192.168.7.70"
        self.assertEqual(ddns.point(f, "vpn.example.org", "192.168.7.70", opener, resolve=lambda n: "198.51.100.9"), "198.51.100.9")
        self.assertEqual(seen, ["https://user:s3cret@ddns.example/update?hostname=vpn.example.org&myip=192.168.7.70"])
        with self.assertRaises(KiwiError) as e:
            ddns.point(f, "vpn.example.org", "1.2.3.4", lambda url: (200, "badauth"), resolve=lambda n: "")
        self.assertNotIn("s3cret", str(e.exception))
        write(f.resolve_path(ddns.FILE), "http://ddns.example/u?ip={address}\n")
        with self.assertRaisesRegex(KiwiError, "must be https"):
            ddns.point(f, "vpn.example.org", "1.2.3.4", opener)
        self.assertTrue(ddns.is_name("vpn.example.org"))
        self.assertFalse(ddns.is_name("188.68.38.110"))

    def test_a_standby_of_another_name_is_refused(self):
        with self.assertRaises(KiwiError):
            self.fleet({"defaults": self.base_defaults(), "hosts": {
                "gate": {"role": "master", "target": "debian", "master": self.master(), "standby": {"store": {}}},
                "store": {"role": "bare"}}})


