    def media_fleet(self):
        return self.fleet({"defaults": self.base_defaults(), "hosts": {
            "gate": {"role": "master", "target": "debian", "master": self.master()}}})

    def test_script_is_bare_unless_offline(self):
        f = self.media_fleet()
