class TestHealth(Base):
    """What is wrong, kept over time (health.py), and the messages about it (notify.py)."""

    def test_a_thing_is_told_once_when_it_lasts_and_once_when_it_is_fine_again(self):
        from kiwiserver import health, notify
        st = {}
        ms = [{"name": "papaya", "ok": True, "problems": [{"level": "warn", "text": "disk /var is 91% full"}]},
              {"name": "lychee", "ok": False, "problems": [{"level": "bad", "text": "not said: it is gone"}]}]
        sv = [{"site": "cloud.papaya.home", "host": "papaya", "admin": False, "ok": False},
              {"site": "chat.example.org", "host": "papaya", "admin": False, "ok": False, "public": True},
              {"site": "control.papaya.home", "host": "papaya", "admin": True, "ok": True},
              {"site": "portainer.lychee.home", "host": "lychee", "admin": True, "ok": False}]
        self.assertEqual(health.update(st, ms, sv, [], 1000), [])                    # a moment is not told: a restart is shorter
        ms[0]["problems"][0]["text"] = "disk /var is 92% full"                       # the same problem, another number
        events = health.update(st, ms, sv, [], 1000 + 600)
        self.assertEqual(sorted(e["text"] for e in events), [
            "Chat does not answer (chat.example.org)", "Files (Nextcloud) does not answer (cloud.papaya.home)",
            "lychee does not answer", "papaya: disk /var is 92% full"])
        self.assertEqual(health.update(st, ms, sv, [], 2200), [])                    # told once
        title, text, level = health.message(events, "home")
        self.assertEqual((title, level), ("Kiwi home: 4 things need a look", "bad"))
        self.assertIn("Wrong: lychee does not answer", text)
        pub = health.public(st, 2200)
        self.assertEqual([(x["site"], x["ok"]) for x in pub["services"]],
                         [("chat.example.org", False), ("cloud.papaya.home", False)])                         # no admin page
        self.assertEqual(pub["machines"], {"on": 1, "of": 2})
        self.assertEqual(sorted(i["text"] for i in pub["incidents"]),
                         ["Chat does not answer", "Files (Nextcloud) does not answer", "lychee does not answer"])
        # for the Internet: only what is open to it, nothing about the machines or the VPN's services
        out = health.public(st, 2200, strangers=True)
        self.assertEqual([x["site"] for x in out["services"]], ["chat.example.org"])
        self.assertEqual((out["machines"], out["window"]), ({}, ""))
        self.assertEqual([i["text"] for i in out["incidents"]], ["Chat does not answer"])
        # not asked this time (this computer is not on the network): nothing is said about services
        self.assertEqual(health.update(st, ms, None, [], 2300), [])
        ms[0]["problems"], ms[1]["ok"], ms[1]["problems"] = [], True, []
        for x in sv:
            x["ok"] = True
        events = health.update(st, ms, sv, [], 4000)
        self.assertEqual(sorted(e["text"] for e in events), [
            "Chat answers again (chat.example.org), after 50 minutes",
            "Files (Nextcloud) answers again (cloud.papaya.home), after 50 minutes", "lychee answers again, after 50 minutes",
            "papaya: no longer so: disk /var is 92% full, after 50 minutes"])
        self.assertEqual(health.message(events, "home")[::2], ("Kiwi home: fine again", "info"))
        self.assertTrue(all(i["to"] == 4000 for i in st["incidents"]))
        self.assertEqual(st["items"], {})
        # how much a machine's parts are needed: one the network needs is told after two minutes, one
        # whose parts can all wait not at all
        st2 = {}
        need = [{"name": "gate", "ok": False, "problems": [], "need": "must"}, {"name": "toy", "ok": False, "problems": [], "need": "wait"},
                {"name": "pi", "ok": False, "problems": []}]
        health.update(st2, need, [], [], 0)
        self.assertEqual([e["text"] for e in health.update(st2, need, [], [], 130)], ["gate does not answer"])
        self.assertEqual([e["text"] for e in health.update(st2, need, [], [], 700)], ["pi does not answer"])
        self.assertNotIn("machine:toy", st2["items"])
        # it counts from when the machine fell silent, as the watchdog says, not from this look
        st4 = {}
        gone = [{"host": "gate", "kind": "waiting", "text": "gate has not answered for 2 minutes", "since": 880}]
        told = health.update(st4, [{"name": "gate", "ok": False, "problems": [], "need": "must"}], [], gone, 1000)
        self.assertEqual([(e["level"], e["text"]) for e in told], [("emergency", "gate has not answered for 2 minutes")])
        # a question nobody answers (a part a person switches): said at once, then after 1, 6 and 24 hours, then daily
        st5, ask = {}, [{"host": "pi", "kind": "tell", "part": "vault", "text": "pi has not answered; vault: kiwi-server switch, by hand"}]
        when = [t for t in range(0, 4 * 86400, 600) if health.update(st5, [], [], ask, t)]
        self.assertEqual(when, [0, 3600, 6 * 3600, 24 * 3600, 48 * 3600, 72 * 3600])
        self.assertTrue(health.update({"did": {"pi:tell:vault": 100}}, [], [], ask, 4000))     # kept from before: told again
        # an emergency: a machine the network needs is gone. Told on every way, again every 15 minutes, until
        # someone has it (docs/design/authority.md)
        st3 = {}
        must = [{"name": "gate", "ok": False, "problems": [], "need": "must"}]
        health.update(st3, must, [], [], 0)
        first = health.update(st3, must, [], [], 130)
        self.assertEqual([(e["level"], e["key"]) for e in first], [("emergency", "machine:gate")])
        title, text, level = health.message(first, "home", "https://control.papaya.home")
        self.assertEqual((title, level), ("Kiwi home, emergency: gate does not answer", "emergency"))
        self.assertIn("I have it (gate): https://control.papaya.home/ack?key=machine:gate", text)
        self.assertEqual(health.update(st3, must, [], [], 600), [])                     # not before 15 minutes
        again = health.update(st3, must, [], [], 130 + 900)
        self.assertIn("Still, for 17 minutes, and nobody said they have it", again[0]["text"])
        acks = {"machine:gate": {"by": "anna", "at": 1100}}
        self.assertEqual(health.update(st3, must, [], [], 130 + 1900, acks=acks), [])  # anna has it: told no more
        self.assertEqual(st3["items"]["machine:gate"]["acked"]["by"], "anna")
        sent = []
        with mock.patch.object(notify, "_mail", lambda c, t, x: sent.append(("mail", tuple(c["to"])))), \
                mock.patch.object(notify, "_ntfy", lambda c, t, x, lv: sent.append(("ntfy", c["url"], lv))):
            cfg = {"mail": {"to": ["me@example.org"], "host": "smtp.example.org"}, "ntfy": {"url": "https://ntfy.example.org/a"},
                   "team": {"mail": ["team@example.org"], "ntfy": "https://ntfy.example.org/team"}}
            notify.send(cfg, title, text, "emergency")
            notify.send(cfg, "x", "y", "bad")
        self.assertEqual(sent, [("mail", ("team@example.org",)), ("ntfy", "https://ntfy.example.org/team", "emergency"),
                                ("mail", ("me@example.org",)), ("ntfy", "https://ntfy.example.org/a", "emergency"),
                                ("mail", ("me@example.org",)), ("ntfy", "https://ntfy.example.org/a", "bad")])
        # what the control node did by itself is told at once, and not again and again
        did = [{"host": "sorbet", "kind": "restarted", "text": "sorbet did not answer: restarted at its provider"}]
        self.assertEqual([e["kind"] for e in health.update(st, ms, sv, did, 5000)], ["did"])
        self.assertEqual(health.update(st, ms, sv, did, 5100), [])
        # a part switched to its standby by itself: told as done, once
        moved = [{"host": "quince", "kind": "switch", "part": "vault", "to": "medlar",
                  "text": "quince has not answered for 5 minutes; vault is kept ready on medlar, and medlar does not reach it "
                          "either: vault goes to medlar"}]
        told = health.update(st, ms, sv, moved, 5200)
        self.assertEqual([(e["kind"], e["level"]) for e in told], [("did", "warn")])
        self.assertIn("vault goes to medlar", health.message(told, "home")[1])
        self.assertEqual(health.update(st, ms, sv, moved, 5300), [])
        # a page that wants a login answers; a proxy without its service does not
        seen, asked = {"a.home": (True, 200), "b.home": (False, 502)}, []

        def one(site, timeout):
            asked.append(site)
            return seen[site]
        self.assertEqual(health.probe(["a.home", "b.home"], one=one, sleep=lambda s: None), seen)
        self.assertEqual(asked, ["a.home", "b.home", "b.home"])                    # the silent one is asked once more
        lost = iter([(False, "timed out"), (True, 200)])
        self.assertEqual(health.probe(["c.home"], one=lambda site, timeout: next(lost), sleep=lambda s: None), {"c.home": (True, 200)})
        self.assertEqual(health.probe([]), {})
        # a public name is asked at the address strangers come to; the others as before
        how = []

        def where(site, timeout, at=None):
            how.append((site, at))
            return True, 200
        health.probe(["cloud.papaya.home", "chat.example.org"], one=where, at={"chat.example.org": "203.0.113.7"})
        self.assertEqual(sorted(how), [("chat.example.org", "203.0.113.7"), ("cloud.papaya.home", None)])

    def test_a_mail_goes_out_in_a_real_smtp_conversation(self):
        """The mail of a notification against a small SMTP server of the test's own: STARTTLS with
        a certificate the test's CA signed, a login, two receivers, the message with its other
        letters. With smtplib stood in for (the next test) a message no server takes would pass."""
        import base64
        import email
        import email.policy
        import socketserver
        import ssl as sslmod
        from kiwiserver import notify
        ca = os.path.join(self.tmp, "ca")
        key, full = certs.ensure_host_cert(ca, "localhost")
        got = {}

        class Handler(socketserver.StreamRequestHandler):
            def handle(self):
                def say(text):
                    self.wfile.write(text.encode())
                    self.wfile.flush()
                say("220 test ESMTP\r\n")
                tls = False
                while True:
                    line = self.rfile.readline().decode(errors="replace").strip()
                    if not line:
                        break
                    cmd = line.split(" ", 1)[0].upper()
                    if cmd == "EHLO":
                        say("250-test\r\n%s250 8BITMIME\r\n" % ("250-AUTH PLAIN LOGIN\r\n" if tls else "250-STARTTLS\r\n"))
                    elif cmd == "STARTTLS":
                        say("220 go ahead\r\n")
                        ctx = sslmod.SSLContext(sslmod.PROTOCOL_TLS_SERVER)
                        ctx.load_cert_chain(full, key)
                        try:
                            self.connection = ctx.wrap_socket(self.connection, server_side=True)
                        except (OSError, sslmod.SSLError):
                            got["refused"] = True          # the client did not trust the certificate
                            return
                        self.rfile, self.wfile, tls = self.connection.makefile("rb"), self.connection.makefile("wb"), True
                    elif cmd == "AUTH":
                        got["auth"], got["auth_over_tls"] = line, tls
                        say("235 ok\r\n")
                    elif cmd == "MAIL":
                        got["from"] = line
                        say("250 ok\r\n")
                    elif cmd == "RCPT":
                        got.setdefault("to", []).append(line)
                        say("250 ok\r\n")
                    elif cmd == "DATA":
                        say("354 end with a dot\r\n")
                        data = b""
                        while True:
                            more = self.rfile.readline()
                            if more in (b".\r\n", b""):
                                break
                            data += more
                        got["data"] = data
                        say("250 queued\r\n")
                    elif cmd == "QUIT":
                        say("221 bye\r\n")
                        break
                    else:
                        say("502 not here\r\n")
        server = socketserver.ThreadingTCPServer(("127.0.0.1", 0), Handler)
        server.daemon_threads = True
        threading.Thread(target=server.serve_forever, daemon=True).start()
        self.addCleanup(server.server_close)
        self.addCleanup(server.shutdown)
        cfg = {"mail": {"to": ["a@example.org", "b@example.org"], "host": "localhost", "port": server.server_address[1],
                        "user": "kiwi", "password": "the mail password", "from": "kiwi@example.org"}}
        # a server whose certificate nobody here knows: no mail, no password sent, and the reason said without it
        sent = notify.send(cfg, "Kiwi home: Käse", "Wrong: lychee does not answer")
        self.assertEqual([(c, ok) for c, ok, _why in sent], [("mail", False)])
        self.assertNotIn("the mail password", sent[0][2])
        self.assertNotIn("auth", got)
        # with the CA known (as a public mail server's is): the mail goes out
        with mock.patch.dict(os.environ, {"SSL_CERT_FILE": os.path.join(ca, "kiwiCA.pem")}):
            sent = notify.send(cfg, "Kiwi home: Käse", "Wrong: lychee does not answer")
        self.assertEqual(sent, [("mail", True, "")])
        self.assertTrue(got["auth_over_tls"])                                   # the password only inside TLS
        self.assertEqual(base64.b64decode(got["auth"].split()[2]), b"\0kiwi\0the mail password")
        self.assertIn("<kiwi@example.org>", got["from"])
        self.assertEqual(len(got["to"]), 2)
        msg = email.message_from_bytes(got["data"], policy=email.policy.default)
        self.assertEqual((msg["Subject"], msg["From"], msg["To"]), ("Kiwi home: Käse", "kiwi@example.org", "a@example.org, b@example.org"))
        self.assertEqual(msg.get_content().strip(), "Wrong: lychee does not answer")
        self.assertTrue(msg["Date"] and msg["Message-ID"].endswith("@example.org>"))

    def test_messages_go_out_by_mail_push_and_webhook(self):
        import http.server
        from kiwiserver import notify
        got = []

        class Hook(http.server.BaseHTTPRequestHandler):
            def do_POST(self):
                got.append((self.path, dict(self.headers), self.rfile.read(int(self.headers["Content-Length"]))))
                self.send_response(200)
                self.end_headers()

            def do_GET(self):
                got.append((self.path, {}, b""))
                self.send_response(200)
                self.end_headers()

            def log_message(self, *a):
                pass
        srv = http.server.HTTPServer(("127.0.0.1", 0), Hook)
        t = threading.Thread(target=srv.serve_forever, daemon=True)
        t.start()
        self.addCleanup(lambda: (srv.shutdown(), srv.server_close(), t.join(5)))
        url = "http://127.0.0.1:%d" % srv.server_port
        mails = []

        class Smtp:
            def __init__(self, host, port, timeout=None):
                mails.append(["to %s:%d" % (host, port)])

            def __enter__(self):
                return self

            def __exit__(self, *a):
                pass

            def starttls(self, context=None):
                mails[-1].append("starttls")

            def login(self, user, password):
                mails[-1].append("login %s" % user)

            def send_message(self, msg):
                mails[-1].append((msg["To"], msg["Subject"], msg.get_content()))
        cfg = {"mail": {"to": ["a@example.org", "b@example.org"], "host": "smtp.example.org", "user": "kiwi", "password": "pw"},
               "ntfy": {"url": url + "/topic", "token": "tk"}, "webhook": {"url": url + "/hook"}}
        self.assertEqual(notify.channels(cfg), ["mail", "ntfy", "webhook"])
        self.assertEqual(notify.channels({"mail": {"to": ["a@example.org"]}}), [])        # no server: not set
        with mock.patch.object(notify.smtplib, "SMTP", Smtp):
            sent = notify.send(cfg, "Kiwi home: Käse", "Wrong: lychee does not answer", "bad", "home")
        self.assertEqual(sent, [("mail", True, ""), ("ntfy", True, ""), ("webhook", True, "")])
        self.assertEqual(mails, [["to smtp.example.org:587", "starttls", "login kiwi",
                                  ("a@example.org, b@example.org", "Kiwi home: Käse", "Wrong: lychee does not answer\n")]])
        push, hook = got
        self.assertEqual((push[0], push[1]["Priority"], push[1]["Authorization"], push[2]),
                         ("/topic", "high", "Bearer tk", b"Wrong: lychee does not answer"))
        self.assertTrue(push[1]["Title"].startswith("=?UTF-8?B?"))                       # a header takes plain letters only
        self.assertEqual(json.loads(hook[2]), {"title": "Kiwi home: Käse", "text": "Wrong: lychee does not answer",
                                               "level": "bad", "network": "home"})
        # a channel that fails says why and does not stop the others
        bad = dict(cfg, ntfy={"url": "http://127.0.0.1:1/x"})
        with mock.patch.object(notify.smtplib, "SMTP", Smtp):
            sent = notify.send(bad, "t", "x")
        self.assertEqual([(c, ok) for c, ok, _w in sent], [("mail", True), ("ntfy", False), ("webhook", True)])
        self.assertTrue(notify.heartbeat(url + "/beat"))
        self.assertFalse(notify.heartbeat("http://127.0.0.1:1/x"))

    def test_the_command_keeps_what_is_wrong_and_says_what_changed(self):
        from kiwiserver import health
        f = self.fleet({"defaults": self.base_defaults(notify={"after": 0}), "hosts": {"a": {}}})
        status = os.path.join(self.tmp, "status.json")
        write(status, json.dumps({"hosts": [{"host": "a", "ok": True, "problems": [{"level": "bad", "text": "the disk is full"}]}]}))
        state = os.path.join(self.tmp, "health.json")
        rows = {"hosts": [{"name": "a", "phase": "applied", "sites": ["cloud.a.home", "control.a.home"],
                           "admin_sites": ["control.a.home"]}]}
        real = cli.main

        def fake_main(argv):
            if argv[:1] == ["list"]:
                print(json.dumps(rows))
                return 0
            return real(argv)
        answers = {"cloud.a.home": (False, 502), "control.a.home": (True, 403)}
        out = io.StringIO()
        with mock.patch.object(cli, "main", fake_main), mock.patch.object(health, "probe", lambda sites, **kw: {s: answers[s] for s in sites}), \
                contextlib.redirect_stdout(out):
            cli.cmd_notify(argparse.Namespace(fleet=f.path, test=False, status=status, events=None, state=state, no_send=False,
                                              porcelain=True, output=None, media=None))
        said = json.loads(out.getvalue().strip().splitlines()[-1])
        self.assertEqual(sorted(e["text"] for e in said["events"]),
                         ["Files (Nextcloud) does not answer (cloud.a.home)", "a: the disk is full"])
        self.assertEqual((said["sent"], said["down"]), ([], ["cloud.a.home"]))            # nowhere to send it: kept only
        kept = json.loads(util.read_text(state))
        self.assertEqual(sorted(kept["items"]), ["problem:a:the disk is full", "service:cloud.a.home"])
        self.assertEqual(kept["window"], "Sun 03:30")
        with self.assertRaisesRegex(KiwiError, "nowhere to send it yet"):
            cli.cmd_notify(argparse.Namespace(fleet=f.path, test=True, output=None, media=None))


    def test_the_messages_password_and_token_live_in_the_secret_store(self):
        """`secrets keep` takes notify's mail password and ntfy token out of the fleet file too; the
        messages still go out with them."""
        f = self.fleet({"defaults": self.base_defaults(notify={
            "mail": {"host": "smtp.example.org", "user": "u", "password": "mail-pw-of-the-test", "to": "a@example.org"},
            "ntfy": {"url": "https://ntfy.example.org/topic", "token": "tk-of-the-test"}}), "hosts": {"a": {}}})
        os.makedirs(os.path.join(os.path.dirname(f.path), "secrets"), exist_ok=True)
        err = io.StringIO()
        with contextlib.redirect_stderr(err), contextlib.redirect_stdout(io.StringIO()):
            cli.main(["validate", f.path])
        self.assertIn("notify.mail.password: a password written in the fleet file", err.getvalue())
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            cli.secrets_keep(f.path, types.SimpleNamespace(is_open=lambda: True, exists=lambda: True, sync=lambda: None))
        text = util.read_text(f.path)
        self.assertNotIn("of-the-test", text)
        self.assertIn("smtp.example.org", text)                                        # the rest stays
        cfg = cli.notify_config(config.Fleet.load(f.path))
        self.assertEqual((cfg["mail"]["password"], cfg["ntfy"]["token"]), ("mail-pw-of-the-test", "tk-of-the-test"))

class TestBanned(unittest.TestCase):
    def test_a_machine_says_how_many_addresses_fail2ban_keeps_out(self):
        from kiwiserver import facts
        f = facts.parse("now=1\nbanned=2\n", local_now=1)
        self.assertEqual(f["banned"], 2)
        self.assertNotIn("banned", facts.parse("now=1\n", local_now=1))          # no fail2ban on the machine: nothing said
        self.assertTrue(set(facts.parse("")) <= set(f))                          # an optional fact: not one every machine has


class TestMadeUpNetwork(unittest.TestCase):
    """The made-up network of the page and app previews (tests/drills/madeup.py) says what real
    machines say: a field the app or the page reads must not be missing from it."""

    def test_its_machines_answer_like_real_ones(self):
        sys.path.insert(0, os.path.join(ROOT, "tests", "drills"))
        self.addCleanup(sys.path.pop, 0)
        import madeup
        from kiwiserver import facts
        listed, status = madeup.answers()
        self.assertEqual([h["name"] for h in listed["hosts"]], [h["host"] for h in status["hosts"]])
        answering = [h for h in status["hosts"] if h["ok"]]
        self.assertTrue(answering and len(answering) < len(status["hosts"]))          # one does not answer
        for h in answering:
            self.assertEqual(set(facts.parse("")) - set(h["facts"]), set(), h["host"])
        for h in status["hosts"]:
            self.assertEqual({"host", "target", "ok", "output", "state", "problems", "notes", "facts"} - set(h), set())
        self.assertEqual(sorted(yaml.safe_load(madeup.fleet_yaml())["hosts"]),
                         sorted(h["name"] for h in listed["hosts"] if not h.get("standby_of")))     # a standby is its master's block
        # its plan of a move has what the real plan has (the Move page reads it)
        from kiwiserver import partmove
        real = partmove.plan(type("F", (), {"hosts": {}})(), {}, type("M", (), {"modules": {}})(), "vault", "a", "b")
        made = madeup.move_plan("vault", "papaya", "lychee")
        self.assertEqual(set(real) - {"data", "name_setting", "name_value"} - set(made), set())
        self.assertTrue(made["steps"] and not made["stops"])
        self.assertTrue(madeup.move_plan("vault", "lychee", "papaya")["stops"])           # lychee has no vault
        r = subprocess.run([sys.executable, os.path.join(ROOT, "tests", "drills", "madeup.py"), "status", "x", "--porcelain"],
                           capture_output=True, text=True)
        self.assertEqual(json.loads(r.stdout), status)


class WebBase(StoreBase):
    """The pages over a real socket, asked the way a browser asks: a form posted under the
    proxy's no-referrer policy carries `Origin: null`."""
    PW = "a long enough password"

    def setUp(self):
        super().setUp()
        import uvicorn
        from kiwiserver import web
        self.init()
        fake = [sys.executable, "-c", "import sys; print('ran', *sys.argv[1:])"]
        self.c = controlmod.Control(self.f.path, kiwi_cmd=fake, run_dir=os.path.join(self.tmp, "ram"))
        self.c.set_password(self.PW)
        store.Store.for_fleet(self.f.path).lock()                # as on a node that just started
        port = remote.free_port()
        self.server = uvicorn.Server(uvicorn.Config(web.make_app(self.c), host="127.0.0.1", port=port, log_level="error"))
        t = threading.Thread(target=self.server.run, daemon=True)
        t.start()
        self.addCleanup(lambda: (setattr(self.server, "should_exit", True), t.join(5)))
        self.url = "http://127.0.0.1:%d" % port
        for _ in range(100):
            if self.server.started:
                break
            time.sleep(0.05)
        self.cookie = ""

    def ask(self, path, form=None, origin="null"):
        """(status, Location or body). A form is posted with the Origin a browser sends."""
        import urllib.error
        import urllib.request

        class Stay(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *a, **kw):
                return None
        headers = {"Cookie": self.cookie} if self.cookie else {}
        data = None
        if form is not None:
            data = urllib.parse.urlencode(form).encode()
            headers["Origin"] = origin
        req = urllib.request.Request(self.url + path, data=data, headers=headers)
        try:
            with urllib.request.build_opener(Stay).open(req) as r:
                return r.status, r.read().decode()
        except urllib.error.HTTPError as e:
            set_cookie = e.headers.get("set-cookie") or ""
            if set_cookie.startswith("kiwi_session=") and '""' not in set_cookie.split(";")[0]:
                self.cookie = set_cookie.split(";")[0]
            with e:
                return e.code, e.headers.get("location") or e.read().decode()



@unittest.skipUnless(have("age") and have("age-keygen") and _have_web(), "age, fastapi or uvicorn not installed")
class TestWeb(WebBase):
    """The control page's own pages."""

    def wait_look(self, seconds=60):
        """The look a login starts writes fleet.json and status.json too: a test writes its own after it."""
        end = time.time() + seconds
        while self.c.looking and time.time() < end:
            time.sleep(0.05)
        self.assertFalse(self.c.looking, "the look the login started did not end")

    def test_a_machine_with_wake_on_lan_that_does_not_answer_can_be_woken(self):
        self.assertEqual(self.ask("/login", {"password": self.PW})[0], 303)
        self.wait_look()                    # the look the login started writes these files too: after it
        util.write_text(os.path.join(self.c.run, "fleet.json"), json.dumps({"hosts": [
            {"name": n, "hostname": n + ".home", "role": "node", "modules": [], "sites": [], "next": "", "wol": n == "fig"}
            for n in ("fig", "papaya")]}))
        gone = {"level": "bad", "text": "unreachable: no answer", "key": "unreachable"}
        util.write_text(os.path.join(self.c.run, "status.json"), json.dumps({"time": time.time(), "hosts": [
            {"host": n, "state": "bad", "problems": [gone], "notes": [], "facts": {}} for n in ("fig", "papaya")]}))
        body = self.ask("/hosts/fig")[1]
        self.assertIn('<input type="hidden" name="action" value="wake">', body)
        self.assertIn("Wake it", body)
        self.assertNotIn("Wake it", self.ask("/hosts/papaya")[1])             # no Wake-on-LAN: no button
        # asleep in its window (asleep): said so, no problem, and woken on purpose if wanted
        util.write_text(os.path.join(self.c.run, "status.json"), json.dumps({"time": time.time(), "hosts": [
            {"host": "fig", "state": "asleep", "problems": [], "notes": ["asleep until 02:30 (by its clock)"], "facts": {}}]}))
        body = self.ask("/hosts/fig")[1]
        self.assertIn("Asleep until 02:30", body)
        self.assertIn("Wake it now", body)

    def test_changes_not_applied_yet_are_applied_with_one_button(self):
        """Save & apply, and the Home card (after OpenWrt): a change reaches other machines too."""
        self.assertEqual(self.ask("/login", {"password": self.PW})[0], 303)
        info = {"hosts": [{"name": n, "hostname": n + ".home", "role": "node", "phase": "applied", "modules": [], "sites": []}
                          for n in ("papaya", "lime", "sorbet")], "changed": ["lime", "sorbet"]}
        util.write_text(os.path.join(self.c.run, "fleet.json"), json.dumps(info))
        body = self.ask("/")[1]
        self.assertIn("Changes not applied yet", body)
        self.assertIn("Apply all 2", body)
        self.assertIn('<input type="hidden" name="host" value="sorbet">', body)
        csrf = re.search(r'name="csrf" value="([^"]+)"', body).group(1)
        with mock.patch.object(self.c, "settings", lambda host: {"groups": []}), \
                mock.patch.object(self.c, "save_settings", lambda host, changes, user="admin": []), \
                mock.patch.object(self.c, "fleet_info", lambda fresh=False: info):
            code, where = self.ask("/hosts/papaya/settings", {"csrf": csrf, "then": "apply"})[:2]
            self.assertEqual(code, 303)
            jid = where.rsplit("/", 1)[1]
