    # ---- the network's own copy: fetched from the page, brought back on a new machine ----
    def fetch(self, path, cookie=""):
        """A GET that may be a download: (status, headers, bytes)."""
        import urllib.error
        import urllib.request

        class Stay(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *a, **kw):
                return None
        req = urllib.request.Request(self.url + path, headers={"Cookie": cookie} if cookie else {})
        try:
            with urllib.request.build_opener(Stay).open(req) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            with e:
                return e.code, e.headers, e.read()

    def send(self, path, fields, files, cookie=""):
        """A form with a file in it, as a browser sends one (multipart/form-data):
        (status, body or Location, the session cookie it set)."""
        import urllib.error
        import urllib.request

        class Stay(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *a, **kw):
                return None
        mark = "----kiwi" + os.urandom(8).hex()
        body = b""
        for name, value in fields.items():
            body += ('--%s\r\nContent-Disposition: form-data; name="%s"\r\n\r\n%s\r\n' % (mark, name, value)).encode()
        for name, (filename, data) in files.items():
            body += ('--%s\r\nContent-Disposition: form-data; name="%s"; filename="%s"\r\n'
                     'Content-Type: application/octet-stream\r\n\r\n' % (mark, name, filename)).encode() + data + b"\r\n"
        body += ("--%s--\r\n" % mark).encode()
        headers = {"Content-Type": "multipart/form-data; boundary=" + mark}
        if cookie:
            headers["Cookie"] = cookie
        req = urllib.request.Request(self.url + path, data=body, headers=headers)
        try:
            with urllib.request.build_opener(Stay).open(req) as r:
                return r.status, r.read().decode(), (r.headers.get("set-cookie") or "").split(";")[0]
        except urllib.error.HTTPError as e:
            with e:
                return e.code, e.headers.get("location") or e.read().decode(), (e.headers.get("set-cookie") or "").split(";")[0]

    def another_machine(self):
        """A second machine with nothing on it, and its page: (its Control, its folder, its address)."""
        import uvicorn
        from kiwiserver import web
        folder = os.path.join(self.tmp, "node2")
        os.makedirs(folder)
        c = controlmod.Control(os.path.join(folder, "fleet.yaml"), run_dir=os.path.join(self.tmp, "ram2"),
                               kiwi_cmd=[sys.executable, "-c", "print('ran')"])
        port = remote.free_port()
        server = uvicorn.Server(uvicorn.Config(web.make_app(c), host="127.0.0.1", port=port, log_level="error"))
        t = threading.Thread(target=server.run, daemon=True)
        t.start()
        self.addCleanup(lambda: (setattr(server, "should_exit", True), t.join(5)))
        for _ in range(100):
            if server.started:
                break
            time.sleep(0.05)
        return c, folder, "http://127.0.0.1:%d" % port

    def disk_of(self, folder):
        """What a machine's disk holds: every file that is not a link into memory, with its bytes."""
        found = {}
        for root, _dirs, files in os.walk(folder):
            for f in files:
                path = os.path.join(root, f)
                if not os.path.islink(path):
                    with open(path, "rb") as fh:
                        found[os.path.relpath(path, folder)] = fh.read()
        return found

    def test_a_copy_is_fetched_and_brings_the_network_back_on_a_new_machine(self):
        from kiwiserver import web
        _s, body, cookie = self.ask("/setup", dict(self.FORM, password=self.PW, again=self.PW, code=self.c.setup_code()))
        recovery = re.search(r"AGE-SECRET-KEY-[A-Z0-9]+", body).group(0)
        machines = sorted(config.Fleet.load(os.path.join(self.dir, "fleet.yaml")).hosts)
        self.assertEqual(len(machines), 2)
        # the copy: only for someone who is logged in, made in memory, nothing of it kept here
        self.assertEqual(self.ask("/backups/network.tar")[:2], (303, "/login"))
        self.assertIn("Fetch a copy", self.ask("/backups", cookie=cookie)[1])
        self.assertIn("A copy and your recovery key are the whole network", self.ask("/backups", cookie=cookie)[1])
        status, headers, data = self.fetch("/backups/network.tar", cookie)
        self.assertEqual(status, 200)
        self.assertRegex(headers["content-disposition"], r'^attachment; filename="fleet-fleet-\d{8}T\d{6}Z\.tar"$')
        self.assertEqual(backup.kind(data), "store")
        with tarfile.open(fileobj=io.BytesIO(data)) as tar:
            self.assertEqual(tar.getnames(), ["MANIFEST.json", "secrets.age", "secrets.recipients", "fleet.yaml.age"])
        self.assertNotIn(b"203.0.113.7", data)
        self.assertEqual([f for _r, _d, files in os.walk(self.tmp) for f in files if f.endswith(".tar")], [])
        self.assertIn("fetched a copy of the network", str(self.c.audit_tail(5)))
        self.c.lock_store()                                 # that machine is lost; from here on, a new one's page
        c2, folder, self.url = self.another_machine()
        new = "the new machine's password"
        form = {"recovery": recovery, "code": c2.setup_code(), "password": new, "again": new}
        copy = {"copy": ("fleet-fleet.tar", data)}
        self.assertIn("I already have a network: bring it back from a copy", self.ask("/setup")[1])
        # what is wrong is said on the page, and nothing is brought back
        for wrong, files, says in ((dict(form, code="0000-0000"), copy, "That is not the setup code"),
                                   (dict(form, recovery=store.keygen()[0]), copy, "That recovery key does not open this copy."),
                                   (dict(form, again="another one, long too"), copy, "The two passwords are not the same."),
                                   (dict(form, password="short", again="short"), copy, "12 characters at least"),
                                   (form, {}, "Choose the copy")):
            status, body, got = self.send("/setup/restore", wrong, files)
            self.assertEqual(status, 200)
            self.assertIn(says, body)
            self.assertIn("<details class=\"card\" open>", body)       # the card is open, with what went wrong
            self.assertEqual(got, "")
            self.assertNotIn(recovery, body)
            self.assertTrue(c2.fresh())
            self.assertEqual(sorted(n for n in self.disk_of(folder) if n != "control/audit.jsonl"), [])
        with mock.patch.object(web, "COPY_MAX", 1000):      # a file that cannot be a copy: refused, whatever it holds
            for files in (copy, {"copy": ("big.iso", b"\0" * 200000)}):
                status, body, _c = self.send("/setup/restore", form, files)
                self.assertEqual(status, 413)
                self.assertIn("too large to be a copy of a network", body)
        status, body, _c = self.ask("/setup/restore", form)             # a form without a file part
        self.assertEqual(status, 200)
        self.assertIn("did not arrive whole", body)
        self.assertTrue(c2.fresh())
        self.assertEqual(sorted(n for n in self.disk_of(folder) if n != "control/audit.jsonl"), [])
        # the copy, the recovery key (as a person types it) and a new password
        status, where, cookie = self.send("/setup/restore", dict(form, recovery=" %s " % recovery.lower()), copy)
        self.assertEqual((status, where), (303, "/"))
        self.assertTrue(cookie.startswith("kiwi_session="))
        self.assertFalse(c2.fresh())
        self.assertFalse(c2.locked())
        # at rest: the encrypted files only, as after a first run
        rest = self.disk_of(folder)
        self.assertEqual(sorted(rest), ["control/audit.jsonl", "control/salt", "fleet.yaml.age", "secrets.age", "secrets.recipients"])
        for name, blob in rest.items():
            for plain in (b"203.0.113.7", b"AGE-SECRET-KEY", recovery.lower().encode(), new.encode(), self.PW.encode()):
                self.assertNotIn(plain, blob, name)
        self.assertTrue(os.path.islink(os.path.join(folder, "fleet.yaml")))
        self.assertFalse(os.path.exists(os.path.join(c2.run, "restore-run")))
        self.assertEqual(sorted(config.Fleet.load(os.path.join(folder, "fleet.yaml")).hosts), machines)
        self.assertEqual([n for n, _k in c2.store.ways()], ["recovery", "control"])
        self.assertIn("brought back from a copy", str(c2.audit_tail(5)))
        self.assertEqual(self.ask("/setup")[:2], (303, "/login"))
        self.assertEqual(self.send("/setup/restore", form, copy)[:2], (303, "/login"))
        # the password of the page that was lost opens nothing here; the new one does
        c2.lock_store()
        self.assertIsNone(c2.login(self.PW, "10.0.0.1"))
        self.assertTrue(c2.locked())
        self.assertEqual(self.ask("/login", {"password": new})[:2], (303, "/"))
        self.assertFalse(c2.locked())
        # its page is the network's now, and shows the machines to compare
        c2.kiwi = [sys.executable, "-c", "import sys; sys.path.insert(0, %r); from kiwiserver import cli; "
                   "sys.exit(cli.main(sys.argv[1:]))" % os.path.join(ROOT, "lib")]
        c2.fleet_info(fresh=True)
        body = self.ask("/", cookie=cookie)[1]
        for name in machines:
            self.assertIn(name, body)

    def test_the_setup_code_reaches_a_log_at_once(self):
        # a container's log is a pipe, not a terminal: what is printed must not wait in a buffer,
        # or `podman logs` shows no code for the page to ask for
        import select
        folder = os.path.join(self.tmp, "node3")
        os.makedirs(folder)
        env = {k: v for k, v in os.environ.items() if k != "PYTHONUNBUFFERED"}
        env["PYTHONPATH"] = os.path.join(ROOT, "lib")
        p = subprocess.Popen([sys.executable, "-m", "kiwiserver", "serve", os.path.join(folder, "fleet.yaml"), "--wait",
                              "--listen", "127.0.0.1:%d" % remote.free_port()], stdout=subprocess.PIPE,
                             stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL, env=env)
        try:
            said = b""
            while b"serving" not in said and select.select([p.stdout], [], [], 30)[0]:
                more = os.read(p.stdout.fileno(), 4096)
                if not more:
                    break
                said += more
            self.assertIsNone(p.poll())                                 # it serves; nothing was flushed by an exit
            self.assertRegex(said.decode(), r"setup code: [0-9a-f]{4}-[0-9a-f]{4}\n")
        finally:
            p.terminate()
            p.wait(10)
            p.stdout.close()

    def test_save_it_now_needs_no_passphrase_on_a_network_made_here(self):
        _s, body, cookie = self.ask("/setup", dict(self.FORM, password=self.PW, again=self.PW, code=self.c.setup_code()))
        recovery = re.search(r"AGE-SECRET-KEY-[A-Z0-9]+", body).group(0)
        self.c.kiwi = [sys.executable, "-c", "import sys; sys.path.insert(0, %r); from kiwiserver import cli; "
                       "sys.exit(cli.main(sys.argv[1:]))" % os.path.join(ROOT, "lib")]
        self.c.fleet_info(fresh=True)
        csrf = re.search(r'name="csrf" value="([^"]+)"', self.ask("/", cookie=cookie)[1]).group(1)
        fleet = os.path.join(self.dir, "fleet.yaml")
        # no machine is set up yet: said on the Backups page, with the other way to a copy
        status, body, _c = self.ask("/run", {"action": "backup", "csrf": csrf}, cookie=cookie)
        self.assertEqual(status, 200)
        self.assertIn("Nothing was saved: no machine is set up yet", body)
        self.assertIn("Fetch a copy", body)
        # once machines are set up, the copy goes to them, by name
        info = self.c.fleet_info()
        names = [h["name"] for h in info["hosts"]]
        info["hosts"][0]["phase"] = "applied"
        util.write_text(os.path.join(self.c.run, "fleet.json"), json.dumps(info))
        self.assertEqual(self.c.argv("backup")[-3:], ["backup", fleet, names[0]])
        # the command itself, on a network whose fleet file is a link into memory: a copy, no passphrase
        out = os.path.join(self.tmp, "stick")
        os.makedirs(out)
        r = subprocess.run(self.c.kiwi + ["backup", fleet, "--local", out], capture_output=True, text=True,
                           stdin=subprocess.DEVNULL, cwd=self.dir)
        self.assertEqual(r.returncode, 0, r.stderr)
        self.assertNotIn("passphrase", r.stdout + r.stderr)
        name = os.listdir(out)[0]
        self.assertTrue(name.endswith(".tar"))
        with open(os.path.join(out, name), "rb") as fh:
            fleet_name, plain, _kept = backup.open_copy(fh.read(), recovery)
        self.assertEqual((fleet_name, sorted(plain)), ("fleet.yaml", ["fleet.yaml"]))
        self.assertEqual(sorted(yaml.safe_load(plain["fleet.yaml"])["hosts"]), sorted(names))

    def test_a_look_writes_each_machine_as_it_answers(self):
        cookie, _csrf = self.made()
        names = sorted(self.data()["hosts"])
        util.write_text(os.path.join(self.c.run, "status.json"), json.dumps({"time": 1, "hosts": [
            {"host": names[0], "ok": True, "state": "ok", "problems": [], "notes": [], "facts": {}},
            {"host": "left", "ok": True, "state": "ok", "problems": [], "notes": [], "facts": {}}]}))
        mark = os.path.join(self.tmp, "go")
        script = ("import json, os, sys, time\n"
                  "print(json.dumps({'host': %r, 'ok': False, 'state': 'down', 'problems': [], 'notes': [], 'facts': {}}), flush=True)\n"
                  "while not os.path.exists(%r): time.sleep(0.05)\n"
                  "print(json.dumps({'host': %r, 'ok': True, 'state': 'ok', 'problems': [], 'notes': [], 'facts': {}}), flush=True)\n"
                  % (names[1], mark, names[0]))
        self.c.kiwi = [sys.executable, "-c", script]
        t = threading.Thread(target=self.c.refresh_status)
        t.start()
        for _ in range(100):                        # the first answer is on the page while the second is awaited
            st = self.c.status()
            if any(h["host"] == names[1] and h["state"] == "down" for h in st["hosts"]):
                break
            time.sleep(0.05)
        self.assertEqual({h["host"]: h["state"] for h in st["hosts"]}, {names[0]: "ok", "left": "ok", names[1]: "down"})
        self.assertTrue(self.c.looking)
        write(mark, "")
        t.join(10)
        st = self.c.status()
        self.assertEqual({h["host"]: h["state"] for h in st["hosts"]}, {names[0]: "ok", names[1]: "down"})   # "left" left
        self.assertFalse(self.c.looking)
        self.assertGreater(st["time"], 1)
        # a kiwi-server that answers all at once (before --stream) is still read
        self.c.kiwi = [sys.executable, "-c", "import json; print(json.dumps({'hosts': [{'host': 'a', 'ok': True}]}))"]
        self.assertEqual(self.c.refresh_status()["hosts"], [{"host": "a", "ok": True}])
        self.c.kiwi = [sys.executable, "-c", "import sys; sys.stderr.write('error: boom'); sys.exit(1)"]
        self.assertEqual(self.c.refresh_status()["error"], "error: boom")

    def test_a_new_network_is_linked_from_the_page_by_card(self):
        """The page gives this network's card and takes another's (`federate --invite / --accept`):
        before, linking a new network needed a computer with the fleet."""
        cookie, csrf = self.made()
        script = ("import sys\n"
                  "a = sys.argv\n"
                  "if a[1] == 'federate' and '--invite' in a:\n"
                  "    open(a[a.index('--invite') + 1], 'w').write('federation-card: 1\\nname: mine\\nmesh: 10.9.0.0/16\\n')\n"
                  "if a[1] == 'federate' and '--accept' in a:\n"
                  "    card = open(a[a.index('--accept') + 1]).read()\n"
                  "    if 'federation-card' not in card:\n"
                  "        sys.stderr.write('error: this is not a card\\n'); sys.exit(1)\n"
                  "    print(':: other is a partner of mine now; nothing is shared yet')\n")
        self.c.kiwi = [sys.executable, "-c", script]
        page = self.ask("/federation", cookie=cookie)[1]
        self.assertIn("<summary>Link a new network</summary>", page)
        self.assertIn('href="/federation/card.yaml"', page)
        self.assertNotIn("it is done on the computer that has them", page)
        status, card, _ = self.ask("/federation/card.yaml", cookie=cookie)
        self.assertEqual((status, card), (200, "federation-card: 1\nname: mine\nmesh: 10.9.0.0/16\n"))
        self.assertEqual(self.ask("/federation/card.yaml")[0], 303)                  # not without a login
        status, body, _ = self.ask("/federation/card", {"card": "federation-card: 1\nname: other\n", "csrf": csrf}, cookie=cookie)
        self.assertEqual(status, 200)
        self.assertIn("other is a partner of mine now", body)
        self.assertEqual(self.c.audit_tail(5)[0]["what"], "linked with another network (its card taken)")
        status, body, _ = self.ask("/federation/card", {"card": "something else", "csrf": csrf}, cookie=cookie)
        self.assertIn("this is not a card", body)                                    # said on the page, nothing taken
        self.assertEqual(self.ask("/federation/card", {"card": "federation-card: 1"}, cookie=cookie)[0], 303)   # no token: nothing
        self.assertFalse([f for f in os.listdir(self.c.run) if f.startswith("tmp")])  # the pasted card is not kept

    def test_a_part_moves_and_switches_from_the_page(self):
        """Move, keep ready and switch on a machine's page (the Services tab): the plan first, then a
        job that runs the same command as a terminal would."""
        cookie, csrf = self.made()
        a, b = sorted(self.data()["hosts"])[:2]
        part = self.data()["hosts"][a].get("node", {}).get("modules", ["vault"])[0] if False else "vault"
        argv_log = os.path.join(self.tmp, "argv")
        plan = {"part": part, "from": a, "to": b, "name": "vault.%s.home" % a, "carry": True, "pins": [],
                "steps": ["%s stops on %s, and %s makes one last backup" % (part, a, a), "%s is applied" % b],
                "stops": [], "notes": ["its data stays on %s's disk" % a]}
        script = ("import json, sys\n"
                  "open(%r, 'a').write(' '.join(sys.argv[1:]) + '\\n')\n"
                  "if sys.argv[1] == 'move' and '--porcelain' in sys.argv: print(json.dumps(%r))\n"
                  "if sys.argv[1] == 'move' and 'nowhere' in sys.argv: sys.exit(1)\n" % (argv_log, plan))
        self.c.kiwi = [sys.executable, "-c", script]
        self.assertEqual(self.c.move_plan(part, a, b)["steps"], plan["steps"])
        with self.assertRaisesRegex(KiwiError, "which part"):
            self.c.move_plan("no part!", a, b)
        # the machine's Services tab offers it, to the machines of its kind
        util.write_text(os.path.join(self.c.run, "fleet.json"), json.dumps({"hosts": [
            {"name": a, "hostname": a + ".home", "role": "node", "modules": [part, "backup"], "sites": [], "next": "", "phase": "applied",
             "keep_ready": {}},
            {"name": b, "hostname": b + ".home", "role": "node", "modules": ["backup"], "sites": [], "next": "", "phase": "applied"},
            {"name": "top", "hostname": "top.home", "role": "master", "modules": [], "sites": [], "next": "", "phase": "applied"}]}))
        tab = self.ask("/hosts/%s?tab=services" % a, cookie=cookie)[1]
        self.assertIn('<h2 id="move">Move a part, or keep it ready</h2>', tab)
        self.assertIn('<option value="%s">%s</option>' % (b, b), tab)
        self.assertNotIn('<option value="top">', tab)                        # a master is another kind of machine
        self.assertIn('<option value="%s">' % part, tab)
        status, body, _ = self.ask("/hosts/%s/move?part=%s&to=%s" % (a, part, b), cookie=cookie)
        self.assertEqual(status, 200)
        self.assertIn("makes one last backup", body)                         # the plan, before anything is done
        self.assertIn("It stays <b>vault.%s.home</b>" % a, body)
        self.assertIn('action="/hosts/%s/move"' % a, body)
        self.assertIn("Keep it ready on %s instead" % b, body)
        # the move is a job that runs `move PART FROM TO --yes`
        status, where, _ = self.ask("/hosts/%s/move" % a, {"part": part, "to": b, "csrf": csrf}, cookie=cookie)
        self.assertEqual(status, 303)
        jid = where.rsplit("/", 1)[1]
        for _ in range(200):
            if self.c.job(jid)["state"] in ("ok", "failed"):
                break
            time.sleep(0.05)
        said = util.read_text(argv_log)
        self.assertIn("move %s %s %s %s --yes" % (self.c.fleet_path, part, a, b), said)
        self.assertEqual((self.c.job(jid)["action"], self.c.job(jid)["hosts"]), ("move", [a, b]))
        self.assertEqual(self.ask("/hosts/%s/move" % a, {"part": part, "to": b}, cookie=cookie)[0], 303)   # no token: nothing
        # the switch: `switch PART FROM --yes`, which applies the machines itself (the source answers, or nothing is switched)
        status, where, _ = self.ask("/hosts/%s/switch" % a, {"part": part, "csrf": csrf}, cookie=cookie)
        self.assertEqual(status, 303)
        for _ in range(400):
            if ("switch %s" % self.c.fleet_path) in util.read_text(argv_log) and all(
                    j["state"] in ("ok", "failed") for j in self.c.jobs()):
                break
            time.sleep(0.05)
        said = util.read_text(argv_log)
        self.assertIn("switch %s %s %s --yes" % (self.c.fleet_path, part, a), said)
        self.assertEqual([j for j in self.c.jobs() if j["user"] == "control"], [])
        with self.assertRaisesRegex(KiwiError, "which part"):
            self.c.argv("move", [a], module=part)
        with self.assertRaisesRegex(KiwiError, "which part"):
            self.c.argv("switch", [a, b], module=part)

    def test_a_machine_reports_and_is_looked_at_without_a_login(self):
        """The agent (docs/design/scale.md): a machine's signed report is its state for the look, and
        a machine that was away is looked at, and given what waited for it, the moment it reports."""
        import urllib.error
        import urllib.request
        from kiwiserver import machineagent as agentmod
        cookie, _csrf = self.made()
        a, b = sorted(self.data()["hosts"])[:2]
        fleet = config.Fleet.load(self.c.fleet_path)
        key = agentmod.key(fleet, fleet.hosts[b])
        body = b"what the machine says about itself\n"
        self.c.look = lambda: None

        def post(name, sign, when=None, raw=body):
            when = when or int(time.time())
            req = urllib.request.Request(self.url + "/api/report", data=raw, method="POST", headers={
                "X-Kiwi-Host": name, "X-Kiwi-Time": str(when), "X-Kiwi-Boot": "boot1", "X-Kiwi-Sign": sign(when),
                "Content-Type": "text/plain"})
            try:
                with urllib.request.urlopen(req) as r:
                    heard.append(r.headers.get("X-Kiwi-Hold"))
                    return r.status
            except urllib.error.HTTPError as e:
                with e:
                    return e.code
        heard = []
        good = lambda when: agentmod.signature(key, b, when, "boot1", body)
        # the stand-in for kiwi-server: `status` says ok for a machine with a report in --reports, else down;
        # `apply` applies what it is given
        script = ("import json, os, sys\n"
                  "what, argv = sys.argv[1], sys.argv[2:]\n"
                  "names = [x for x in argv if x in %r]\n"
                  "if what == 'apply':\n"
                  "    for h in names: print(':: %%s: applied' %% h)\n"
                  "if what == 'status':\n"
                  "    d = argv[argv.index('--reports') + 1] if '--reports' in argv else ''\n"
                  "    for h in names or %r:\n"
                  "        up = os.path.isfile(os.path.join(d, h + '.txt'))\n"
                  "        print(json.dumps({'host': h, 'ok': up, 'state': 'ok' if up else 'down', 'problems': [], 'notes': [], 'facts': {}}), flush=True)\n"
                  % ([a, b], [a, b]))
        self.c.kiwi = [sys.executable, "-c", script]
        row = lambda host, state: {"host": host, "ok": state == "ok", "state": state, "problems": [], "notes": [], "facts": {}}
        util.write_text(os.path.join(self.c.run, "status.json"), json.dumps({"time": 1, "hosts": [row(a, "ok"), row(b, "down")]}))
        state = lambda: {h["host"]: h["state"] for h in self.c.status()["hosts"]}

        def settle():
            for _ in range(1200):
                if not self.c._coming and not self.c._retrying and all(j["state"] in ("ok", "failed") for j in self.c.jobs()):
                    return
                time.sleep(0.05)
            self.fail("it did not settle")
        # not its signature, not a machine, an old report: refused, and nothing is kept
        self.assertEqual(post(b, lambda when: "0" * 64), 403)
        self.assertEqual(post("nobody", good), 403)
        self.assertEqual(post(b, good, when=int(time.time()) - 3600), 403)
        self.assertEqual(post(b, lambda when: agentmod.signature(key, b, when, "boot1", b"other")), 403)
        self.assertEqual(self.c.reported(), {})
        self.assertEqual(state()[b], "down")
        # its own: kept, and the machine that was away is looked at from the report at once
        self.assertEqual(post(b, good), 200)
        settle()
        self.assertEqual(util.read_text(os.path.join(self.c.reports_dir, b + ".txt")).encode(), body)
        self.assertEqual(state(), {a: "ok", b: "ok"})
        self.assertEqual(list(self.c.reported()), [b])
        # every /api/NAME answers at /api/v1/NAME too, and the tasks and one machine have their own (ui.md step 5)
        self.c.start("plan", [b], wait=True)
        st, _h, got = self.fetch("/api/v1/jobs", cookie)
        self.assertEqual(st, 200)
        jobs = json.loads(got)["jobs"]
        self.assertTrue(jobs)
        self.assertEqual(json.loads(self.fetch("/api/v1/jobs/%s" % jobs[0]["id"], cookie)[2])["id"], jobs[0]["id"])
        st, _h, got = self.fetch("/api/v1/machines/%s" % b, cookie)
        self.assertEqual((st, json.loads(got)["machine"]["name"]), (200, b))
        self.assertEqual(self.fetch("/api/v1/machines/nobody", cookie)[0], 404)
        self.assertEqual(self.fetch("/api/v1/devices", cookie)[0], self.fetch("/api/devices", cookie)[0])     # an older name
        self.assertEqual(self.fetch("/api/v1/jobs")[0], 401)                              # nobody: nothing
        # an emergency on Home: its text and "I have it"; pressed, it says who has it
        util.write_text(self.c.health_file, json.dumps({"items": {"machine:%s" % b: {
            "kind": "machine", "since": 100, "told": True, "emergency": True, "text": "%s does not answer" % b}}}))
        _st, _h, home = self.fetch("/", cookie)
        self.assertIn(b"Emergency", home)
        self.assertIn(b"I have it", home)
        self.c.ack("machine:%s" % b, "anna")
        _st, _h, home = self.fetch("/", cookie)
        self.assertIn(b"anna has it", home)
        self.assertEqual(self.fetch("/ack?key=machine:%s" % b, cookie)[0], 303)        # the link in the message: Home
        # its last report, when it goes down: kept beside its reports with why, and said in Activity once
        last = b"kiwi-last reboot an update (its update window)\n"
        self.assertEqual(post(b, lambda when: agentmod.signature(key, b, when, "boot1", last), raw=last), 200)
        self.assertEqual(post(b, lambda when: agentmod.signature(key, b, when, "boot1", last), raw=last), 200)
        word = json.loads(util.read_text(os.path.join(self.c.reports_dir, b + ".last")))
        self.assertEqual((word["reason"], word["why"]), ("reboot", "an update (its update window)"))
        self.assertEqual(util.read_text(os.path.join(self.c.reports_dir, b + ".txt")).encode(), body)   # its facts stay
        self.assertTrue(any(e.get("what") == "%s goes down: it restarts (an update (its update window))" % b
                            for e in self.c.audit_tail(5)))
        # an apply that waited for it runs the moment it reports
        self.c._write_waiting({b: {"since": 1, "tries": 0, "user": "admin"}})
        self.c._reported_at.clear()
        self.assertEqual(post(b, good), 200)
        settle()
        self.assertEqual(self.c.waiting(), {})
        own = [j for j in self.c.jobs() if j["user"] == "control"]
        self.assertEqual((len(own), own[0]["hosts"], own[0]["state"]), (1, [b], "ok"))
        # its agent falls silent while the last look calls it up: the next look comes at once, not in ten minutes
        self.assertEqual(self.c.went_silent(), [])
        old = time.time() - 200
        os.utime(os.path.join(self.c.reports_dir, b + ".txt"), (old, old))
        self.assertEqual(self.c.went_silent(), [b])
        gone = time.time() - 7200                                              # silent for hours: the full look's to find
        os.utime(os.path.join(self.c.reports_dir, b + ".txt"), (gone, gone))
        self.assertEqual(self.c.went_silent(), [])
        self.assertIsNone(heard[-1])            # the answer tells the agent nothing to do (22 Nov 2026: no holds)

    def test_jobs_on_different_machines_run_side_by_side(self):
        cookie, _csrf = self.made()
        a, b = sorted(self.data()["hosts"])[:2]
        book, go = os.path.join(self.tmp, "book"), os.path.join(self.tmp, "go3")
        script = ("import os, sys, time\n"
                  "if sys.argv[1] != 'apply': sys.exit(0)\n"
                  "names = [x for x in sys.argv[2:] if x in %r]\n"
                  "open(%r, 'a').write('start %%s\\n' %% ' '.join(names))\n"
                  "while not os.path.exists(%r): time.sleep(0.05)\n"
                  "for h in names: print(':: %%s: applied' %% h)\n" % ([a, b], book, go))
        self.c.kiwi = [sys.executable, "-c", script]
        write(book, "")
        starts = lambda: util.read_text(book).split("\n")[:-1]

        def until(n):
            for _ in range(600):
                if len(starts()) >= n:
                    return
                time.sleep(0.05)
        self.c.start("apply", [a], user="admin")
        self.c.start("apply", [b], user="admin")
        until(2)
        self.assertEqual(sorted(starts()), ["start " + a, "start " + b])      # both run, neither has ended
        self.assertEqual(self.c._busy, {a, b})                                # the look leaves both alone
        third = self.c.start("apply", [a], user="admin")                      # the same machine: after the first
        every = self.c.start("update", user="admin")                          # the whole network: after all of them
        time.sleep(0.5)
        self.assertEqual(len(starts()), 2)
        self.assertEqual(self.c.job(third)["state"], "waiting")
        write(go, "")
        for _ in range(1200):
            if all(j["state"] in ("ok", "failed") for j in self.c.jobs()):
                break
            time.sleep(0.05)
        self.assertEqual([j["state"] for j in self.c.jobs()].count("ok") >= 3, True)
        self.assertEqual(len(starts()), 4)
        self.assertIsNone(self.c._busy)
        self.assertEqual(self.c.job(every)["state"] in ("ok", "failed"), True)
        # a job on the machine this page runs on has the node to itself: its apply restarts the page
        os.environ["KIWI_CONTROL_HOST"] = a
        try:
            self.assertIs(self.c._machines_of({"action": "apply", "hosts": [a]}), controlmod.EVERY)
            self.assertEqual(self.c._machines_of({"action": "apply", "hosts": [b]}), {b})
        finally:
            del os.environ["KIWI_CONTROL_HOST"]
        self.assertIs(self.c._machines_of({"action": "remove", "hosts": [b]}), controlmod.EVERY)

    def test_the_gate(self):
        g, seen = controlmod.Gate(), []

        def job(names, hold):
            with g.machines(names):
                seen.append(("in", tuple(names)))
                hold.wait(5)
                seen.append(("out", tuple(names)))
        h1, h2 = threading.Event(), threading.Event()
        t1 = threading.Thread(target=job, args=(["a"], h1)); t1.start()
        t2 = threading.Thread(target=job, args=(["b"], h2)); t2.start()
        for _ in range(100):
            if len(seen) == 2:
                break
            time.sleep(0.01)
        self.assertEqual(sorted(seen), [("in", ("a",)), ("in", ("b",))])     # side by side
        self.assertTrue(g.locked())
        self.assertFalse(g.acquire(blocking=False))                           # not alone while they work
        alone = []
        t3 = threading.Thread(target=lambda: (g.acquire(), alone.append("alone"), g.release())); t3.start()
        time.sleep(0.1)
        late = threading.Thread(target=job, args=(["c"], threading.Event())); late.start()   # comes after the one who asked
        time.sleep(0.1)
        self.assertEqual((alone, len(seen)), ([], 2))                         # both wait: the asker for the jobs, the job for the asker
        h1.set(); h2.set()
        for t in (t1, t2, t3, late):
            t.join(10)
        self.assertEqual(alone, ["alone"])
        self.assertLess(seen.index(("out", ("b",))), seen.index(("in", ("c",))))
        self.assertFalse(g.locked())
        # a wait with an end: a job that runs on is not waited for to the end, and is not held up after
        hold = threading.Event()
        t4 = threading.Thread(target=job, args=(["d"], hold)); t4.start()
        time.sleep(0.05)
        t0 = time.monotonic()
        self.assertFalse(g.acquire(timeout=0.2))
        self.assertLess(time.monotonic() - t0, 2)
        done = threading.Event(); done.set()
        other = threading.Thread(target=job, args=(["e"], done)); other.start()
        other.join(5)
        self.assertIn(("out", ("e",)), seen)                                  # the next job did not wait for it
        hold.set(); t4.join(5)
        self.assertTrue(g.acquire(timeout=1))
        g.release()

    def test_an_apply_that_did_not_reach_a_machine_waits_for_it(self):
        cookie, _csrf = self.made()
        a, b = sorted(self.data()["hosts"])[:2]
        mode = os.path.join(self.tmp, "mode")
        # the stand-in: `apply` applies a, and b only when the file says "up"; `status` says b down or ok by the same file
        script = ("import json, sys\n"
                  "up = open(%r).read().strip()\n"
                  "what, names = sys.argv[1], [x for x in sys.argv[2:] if x in %r]\n"
                  "if what == 'apply':\n"
                  "    bad = 0\n"
                  "    for h in names:\n"
                  "        if h == %r and up != 'up':\n"
                  "            print('error: %%s: ssh: connect to host: No route to host' %% h); bad = 1\n"
                  "        else:\n"
                  "            print(':: %%s: applied' %% h)\n"
                  "    sys.exit(bad)\n"
                  "if what == 'status':\n"
                  "    for h in %r:\n"
                  "        st = 'down' if h == %r and up == 'off' else 'ok'\n"
                  "        print(json.dumps({'host': h, 'ok': st == 'ok', 'state': st, 'problems': [], 'notes': [], 'facts': {}}), flush=True)\n"
                  % (mode, [a, b], b, [a, b], b))
        self.c.kiwi = [sys.executable, "-c", script]
        ended = lambda: all(j["state"] in ("ok", "failed") for j in self.c.jobs())

        def wait_jobs():
            for _ in range(1200):                       # a minute: the tests run several at once
                if ended() and not self.c._retrying and not self.c.looking and not self.c.look_lock.locked():
                    return
                time.sleep(0.05)
            self.fail("a job or a look did not end")
        self.c.look = lambda: None                      # no look of the page's own beside the ones this test takes
        write(mode, "off")
        jid = self.c.start("apply", [a, b], user="admin", wait=True)
        self.assertEqual(self.c.job(jid)["state"], "failed")
        self.assertEqual(sorted(self.c.waiting()), [b])                     # a got it; b's apply waits
        self.assertEqual(self.c.waiting()[b]["user"], "admin")
        self.c.refresh_status()                                             # b is still off: nothing is started
        wait_jobs()
        self.assertEqual(len(self.c.jobs()), 1)
        self.assertIn("apply waits", self.ask("/machines", cookie=cookie)[1])
        self.assertIn("gets it by itself", self.ask("/hosts/" + b, cookie=cookie)[1])
        write(mode, "up")                                                   # b is back: the look applies it
        self.c.refresh_status()
        wait_jobs()
        jobs = self.c.jobs()
        own = [j for j in jobs if j["user"] == "control"]
        self.assertEqual((len(jobs), len(own), own[0]["hosts"], own[0]["state"]), (2, 1, [b], "ok"))
        self.assertEqual(self.c.waiting(), {})
        self.assertNotIn("apply waits", self.ask("/machines", cookie=cookie)[1])
        # a look at the waiting machines alone (every minute): the others keep what was known, and the last full look its time
        write(mode, "off")
        self.c.start("apply", [b], user="admin", wait=True)
        full = self.c.status()["time"]
        asked = os.path.join(self.tmp, "asked")
        self.c.kiwi = [sys.executable, "-c", "import sys\nopen(%r, 'a').write(' '.join(sys.argv[1:]) + '\\n')\n" % asked + script]
        self.c.refresh_status(only=sorted(self.c.waiting()))
        line = [x.split() for x in util.read_text(asked).strip().split("\n") if x.startswith("status")][-1]
        self.assertEqual((line[0], line[-1], a in line), ("status", b, False))    # only b was asked
        st = self.c.status()
        self.assertEqual(({h["host"]: h["state"] for h in st["hosts"]}, st["time"]), ({a: "ok", b: "down"}, full))
        self.assertFalse(self.c.looking)
        write(mode, "up")
        self.c.refresh_status(only=sorted(self.c.waiting()))                # it answers: applied at once
        wait_jobs()
        self.assertEqual(self.c.waiting(), {})
        self.c.kiwi = [sys.executable, "-c", script]
        # a machine that answers and still fails: tried a few times, then left to a person
        write(mode, "half")                                                 # status says ok, apply fails
        self.c.start("apply", [b], user="admin", wait=True)
        self.assertEqual(sorted(self.c.waiting()), [b])
        for _ in range(self.c.RETRIES + 2):
            self.c.refresh_status()
            wait_jobs()
        self.assertEqual(self.c.waiting(), {})                              # given up
        own = [j for j in self.c.jobs(50) if j["user"] == "control" and j["state"] == "failed"]
        self.assertEqual(len(own), self.c.RETRIES)
        with open(os.path.join(self.c.dir, "audit.jsonl")) as fh:
            self.assertIn("gave up applying %s by itself" % b, fh.read())

    def test_a_look_does_not_wait_for_a_job_on_another_machine(self):
        cookie, _csrf = self.made()
        a, b = sorted(self.data()["hosts"])[:2]
        row = lambda host, state: {"host": host, "ok": True, "state": state, "problems": [], "notes": [], "facts": {}}
        path = os.path.join(self.c.run, "status.json")
        util.write_text(path, json.dumps({"time": 1, "hosts": [row(a, "ok"), row(b, "ok")]}))
        mark = os.path.join(self.tmp, "go2")
        # the stand-in answers "warn" for every machine it is asked about (all of them when none is named)
        script = ("import json, os, sys, time\n"
                  "asked = [x for x in sys.argv[1:] if x in %r] or %r\n"
                  "for h in asked:\n"
                  "    if h == %r:\n"
                  "        while not os.path.exists(%r): time.sleep(0.05)\n"
                  "    print(json.dumps({'host': h, 'ok': True, 'state': 'warn', 'problems': [], 'notes': [], 'facts': {}}), flush=True)\n"
                  % ([a, b], [a, b], b, mark))
        self.c.kiwi = [sys.executable, "-c", script]
        states = lambda: {h["host"]: h["state"] for h in self.c.status()["hosts"]}
        write(mark, "")
        with self.c.lock:                           # a job runs, on machine a only
            self.c._busy = {a}
            t = threading.Thread(target=self.c.refresh_status)
            t.start()
            t.join(10)
            self.assertFalse(t.is_alive())          # the look did not wait for the job
            self.assertEqual(states(), {a: "ok", b: "warn"})    # b was asked; a keeps what was known
            self.c._busy = controlmod.EVERY         # a job on every machine: the look waits for it, as before
            t = threading.Thread(target=self.c.refresh_status)
            t.start()
            time.sleep(0.4)
            self.assertTrue(t.is_alive())
            self.c._busy = None
        t.join(10)
        self.assertFalse(t.is_alive())
        self.assertEqual(states(), {a: "warn", b: "warn"})
        # a job that begins while the look is under way: its machine keeps what was known
        os.remove(mark)
        util.write_text(path, json.dumps({"time": 1, "hosts": [row(a, "ok"), row(b, "ok")]}))
        t = threading.Thread(target=self.c.refresh_status)
        t.start()
        for _ in range(100):
            if states()[a] == "warn":
                break
            time.sleep(0.05)
        self.c._busy = {b}
        write(mark, "")
        t.join(10)
        self.c._busy = None
        self.assertEqual(states(), {a: "warn", b: "ok"})

    def test_reads_are_kept_until_the_fleet_changes(self):
        cookie, _csrf = self.made()
        calls = []
        first = self.c._read_once("x", lambda: calls.append(1) or {"n": len(calls)})
        again = self.c._read_once("x", lambda: calls.append(1) or {"n": len(calls)})
        self.assertEqual((first, again, len(calls)), ({"n": 1}, {"n": 1}, 1))      # asked once
        again["n"] = 99                                                            # a caller's change stays its own
        self.assertEqual(self.c._read_once("x", lambda: {"n": 0}), {"n": 1})
        self.c._gen += 1                                                           # a job ended
        self.assertEqual(self.c._read_once("x", lambda: calls.append(1) or {"n": len(calls)}), {"n": 2})
        path = os.path.realpath(os.path.join(self.dir, "fleet.yaml"))              # the fleet file changed
        os.utime(path, ns=(os.stat(path).st_atime_ns, os.stat(path).st_mtime_ns + 10 ** 9))
        self.assertEqual(self.c._read_once("x", lambda: calls.append(1) or {"n": len(calls)}), {"n": 3})
        with self.assertRaises(KiwiError):                                         # a failure is not kept
            self.c._read_once("y", lambda: (_ for _ in ()).throw(KiwiError("no")))
        self.assertEqual(self.c._read_once("y", lambda: "fine"), "fine")
        # the pages that used to start kiwi-server at every view start it once
        n = []
        real = subprocess.run
        with mock.patch.object(subprocess, "run", lambda *a, **kw: n.append(a[0]) or real(*a, **kw)):
            for _ in range(3):
                self.assertEqual(self.ask("/unlock", cookie=cookie)[0], 200)
                self.assertEqual(self.ask("/recovery", cookie=cookie)[0], 200)
        self.assertEqual(sum(1 for a in n if "unlock" in a), 1)
        self.assertEqual(sum(1 for a in n if "recovery" in a), 1)

